+      window.removeEventListener("mouseup", onMouseUp);
+      canvas.removeEventListener("wheel", onWheel);
+      canvas.removeEventListener("mouseleave", onLeave);
+      window.removeEventListener("keydown", onKey);
+      root.remove();
+    },
+  };
+}
