+/* ── Chrome / top bar (frameless drag region) ─────────────────── */
+
+.nx-chrome,
+.toolbar {
+  display: flex;
+  align-items: center;
+  gap: var(--ds-space-xs);
+  height: var(--ds-chrome-height);
+  padding: 0 var(--ds-space-sm);
+  background: var(--ds-canvas);
+  border-bottom: 1px solid var(--ds-hairline);
+  flex-shrink: 0;
+  /* Entire header is a window drag surface */
+  -webkit-app-region: drag;
+  app-region: drag;
+  user-select: none;
+}
+
+/* Interactive children must opt out of drag or clicks never fire */
+.nx-chrome .nx-no-drag,
+.nx-chrome button,
+.nx-chrome a,
+.nx-chrome input,
+.nx-chrome select,
+.nx-chrome textarea,
+.nx-chrome .nx-btn,
+.nx-chrome .nx-window-controls {
+  -webkit-app-region: no-drag;
+  app-region: no-drag;
+}
+
+.nx-chrome__title {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  min-width: 0;
+  flex: 1;
+  justify-content: center;
+  font-size: 13px;
+  font-weight: 500;
+  color: var(--ds-ink);
+  letter-spacing: 0.01em;
+  /* Keep title in the drag region (double-click maximize still works) */
