+/**
+ * Unified scrollbar styling for the demo shell.
+ * Covers Firefox (scrollbar-*) and Chromium/Electron (-webkit-scrollbar).
+ */
+
+:root {
+  --nx-scrollbar-size: 10px;
+  --nx-scrollbar-thumb: var(--ds-hairline-strong, #d6d3d1);
+  --nx-scrollbar-thumb-hover: var(--ds-muted-soft, #a8a29e);
+  --nx-scrollbar-thumb-active: var(--ds-muted, #777169);
+  --nx-scrollbar-track: transparent;
+  --nx-scrollbar-radius: 999px;
+  --nx-scrollbar-gutter: 2px;
+}
+
+/* Firefox */
+* {
+  scrollbar-width: thin;
+  scrollbar-color: var(--nx-scrollbar-thumb) var(--nx-scrollbar-track);
+}
+
+/* Chromium / Electron */
+*::-webkit-scrollbar {
+  width: var(--nx-scrollbar-size);
+  height: var(--nx-scrollbar-size);
+}
+
+*::-webkit-scrollbar-track {
+  background: var(--nx-scrollbar-track);
+}
+
+*::-webkit-scrollbar-thumb {
+  background-color: var(--nx-scrollbar-thumb);
+  border-radius: var(--nx-scrollbar-radius);
+  border: var(--nx-scrollbar-gutter) solid transparent;
+  background-clip: content-box;
+}
+
+*::-webkit-scrollbar-thumb:hover {
+  background-color: var(--nx-scrollbar-thumb-hover);
+  border: var(--nx-scrollbar-gutter) solid transparent;
+  background-clip: content-box;
+}
+
+*::-webkit-scrollbar-thumb:active {
+  background-color: var(--nx-scrollbar-thumb-active);
+  border: var(--nx-scrollbar-gutter) solid transparent;
+  background-clip: content-box;
+}
+
+*::-webkit-scrollbar-corner {
+  background: transparent;
+}
+
+/* CodeMirror scroller — match shell; slightly denser for long docs */
+.cm-scroller,
+.cm-editor .cm-scroller {
+  scrollbar-width: thin;
+  scrollbar-color: var(--nx-scrollbar-thumb) transparent;
+}
+
+.cm-scroller::-webkit-scrollbar,
+.cm-editor .cm-scroller::-webkit-scrollbar {
+  width: 11px;
+  height: 11px;
+}
+
+.cm-scroller::-webkit-scrollbar-thumb,
+.cm-editor .cm-scroller::-webkit-scrollbar-thumb {
+  background-color: var(--nx-scrollbar-thumb);
+  border-radius: var(--nx-scrollbar-radius);
+  border: 3px solid transparent;
+  background-clip: content-box;
+}
+
+.cm-scroller::-webkit-scrollbar-thumb:hover,
+.cm-editor .cm-scroller::-webkit-scrollbar-thumb:hover {
+  background-color: var(--nx-scrollbar-thumb-hover);
+  border: 3px solid transparent;
+  background-clip: content-box;
+}
+
+/* Panel trees / rails — thinner so sidebars feel lighter */
+.nx-panel-body,
+.nx-sidebar,
+.nx-rail,
+.nexus-vault-panel,
+.nexus-outline-panel,
+.nexus-backlinks-panel {
+  scrollbar-width: thin;
+}
+
+.nx-panel-body::-webkit-scrollbar,
+.nx-sidebar::-webkit-scrollbar,
+.nx-rail::-webkit-scrollbar {
+  width: 8px;
+  height: 8px;
+}
+
+/* Overlay menus keep a compact bar */
+.nx-menu::-webkit-scrollbar,
+.nexus-slash-menu::-webkit-scrollbar {
+  width: 8px;
+}
+
+/* Utility: hide scrollbar but keep scroll (e.g. format bar overflow) */
+.nx-scroll-hidden {
+  scrollbar-width: none;
+}
+.nx-scroll-hidden::-webkit-scrollbar {
+  display: none;
+}

