+/**
+ * Design tokens from DESIGN.md, productized for the editor shell.
+ * Marketing density (64px nav, 96px sections) is tightened for chrome use.
+ *
+ * Color scheme is driven by `html[data-theme="light"|"dark"]` (see applyShellColorScheme).
+ */
+:root,
+html[data-theme="light"] {
+  /* Brand & text */
+  --ds-primary: #292524;
+  --ds-primary-active: #0c0a09;
+  --ds-ink: #0c0a09;
+  --ds-body: #4e4e4e;
+  --ds-body-strong: #292524;
+  --ds-muted: #777169;
+  --ds-muted-soft: #a8a29e;
+  --ds-on-primary: #ffffff;
+
+  /* Surfaces */
+  --ds-canvas: #f5f5f5;
+  --ds-canvas-soft: #fafafa;
+  --ds-surface-card: #ffffff;
+  --ds-surface-strong: #f0efed;
+  --ds-surface-dark: #0c0a09;
+  --ds-surface-dark-elevated: #1c1917;
+
+  /* Hairlines */
+  --ds-hairline: #e7e5e4;
+  --ds-hairline-soft: #f0efed;
+  --ds-hairline-strong: #d6d3d1;
+
+  /* Semantic */
+  --ds-semantic-error: #dc2626;
+  --ds-semantic-success: #16a34a;
+
+  /* Atmospheric (decoration only) */
+  --ds-gradient-mint: #a7e5d3;
+  --ds-gradient-peach: #f4c5a8;
+  --ds-gradient-lavender: #c8b8e0;
+
+  /* Overlays */
+  --ds-overlay: rgba(12, 10, 9, 0.36);
+  --ds-surface-glass: rgba(255, 255, 255, 0.92);
+
+  /* Spacing */
+  --ds-space-xxs: 4px;
+  --ds-space-xs: 8px;
+  --ds-space-sm: 12px;
+  --ds-space-base: 16px;
+  --ds-space-md: 20px;
+  --ds-space-lg: 24px;
+  --ds-space-xl: 32px;
+
+  /* Radius */
+  --ds-radius-xs: 4px;
+  --ds-radius-sm: 6px;
+  --ds-radius-md: 8px;
+  --ds-radius-lg: 12px;
+  --ds-radius-xl: 16px;
+  --ds-radius-pill: 9999px;
+
+  /* Type */
+  --ds-font-ui: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
