+  /* Chrome density */
+  --ds-chrome-height: 48px;
+  /* Shared height for Files / format toolbar / Outline headers so borders align */
+  --ds-panel-header-height: 40px;
+  --ds-icon-btn: 32px;
+  --ds-sidebar-width: 260px;
+  --ds-outline-width: 220px;
+  --ds-shadow-soft: 0 4px 16px rgba(0, 0, 0, 0.04);
+  --ds-shadow-menu: 0 8px 24px rgba(12, 10, 9, 0.12);
+}
+
+/* Dark scheme — DESIGN surface-dark / on-dark family */
+html[data-theme="dark"] {
+  --ds-primary: #fafaf9;
+  --ds-primary-active: #ffffff;
+  --ds-ink: #fafaf9;
+  --ds-body: #d6d3d1;
+  --ds-body-strong: #f5f5f4;
