+
+  --ds-canvas: #0c0a09;
+  --ds-canvas-soft: #141211;
+  --ds-surface-card: #1c1917;
+  --ds-surface-strong: #292524;
+  --ds-surface-dark: #0c0a09;
+  --ds-surface-dark-elevated: #1c1917;
+
+  --ds-hairline: #292524;
